  Centros: 'ማእከላት',
  'Artigos com stock': 'ስቶክ ዘለዎም ኣቕሑ',
  'Stock final nas centrais': 'ናይ መወዳእታ ስቶክ ኣብ ማእከላይ መኻዝን',
  'Sem armazéns ou produtos correspondentes aos filtros aplicados.': 'ምስቶም ዝተተግበሩ መጻረዪታት ዝሰማማዕ መኽዘን ወይ ኣቕሓ የለን።',
  'Posição de stock por artigo e armazém central em {d}.': 'ኩነታት ስቶክ ብኣቕሓን ብማእከላይ መኽዘንን ኣብ {d}።',
  'Pesquisar armazém, centro, artigo ou código…': 'መኽዘን፣ ማእከል፣ ኣቕሓ ወይ ኮድ ድለይ…',
  'sem dados de stock': 'ሓበሬታ ስቶክ የለን',
