  'Em dia: até {a} h; atenção: até {b} h; crítico: mais de {b} h.': 'ብግዜኡ፦ ክሳብ {a} ሰዓት፤ ኣቓልቦ፦ ክሳብ {b} ሰዓት፤ ከቢድ፦ ልዕሊ {b} ሰዓት።',
