  'notas de crédito: −{v}': 'ሰነዳት ክረዲት፦ −{v}',
  'Comunicação AGT': 'ርክብ AGT',
  Comunicados: 'ዝተሓበሩ',
  'Por comunicar': 'ዘይተሓበሩ',
  Comunicado: 'ተሓቢሩ',
  'Data fiscal': 'ዕለት ግብሪ',
  'Estado AGT': 'ኩነታት AGT',
  'Estado do documento': 'ኩነታት ሰነድ',
  'Nome da entidade': 'ስም ኣካል',
  'Não foi possível ler a comunicação à AGT': 'ርክብ AGT ክንብብ ኣይተኻእለን',
  'Sem acesso a esta página.': 'ናብዚ ገጽ ፍቓድ የብልኩምን።',
  'Sem documentos no período.': 'ኣብቲ እዋን ሰነዳት የለን።',
  'Documentos de {a} a {b}, lidos na base de dados do Pinguim BO.': 'ሰነዳት ካብ {a} ክሳብ {b}፡ ካብ ዳታቤዝ Pinguim BO ዝተነበቡ።',
  'A Comunicação AGT precisa do servidor da plataforma (PHP) e da base de dados do Pinguim BO.': 'ርክብ AGT ሰርቨር መድረኽ (PHP)ን ዳታቤዝ Pinguim BOን የድልዮ።',
  'Documentos de vendas do período e o pedido de comunicação à AGT registado no Pinguim BO (DOCHEADEREXTRA).':
    'ሰነዳት መሸጣ ናይቲ እዋንን ኣብ Pinguim BO ዝተመዝገበ ሕቶ ምሕባር ናብ AGTን (DOCHEADEREXTRA)።',
  'Pedido n.º {n}': 'ሕቶ ቁ. {n}',
  'Sem pedido de comunicação': 'ሕቶ ምሕባር የለን',
  '{p} dos documentos': '{p} ካብ ሰነዳት',
  Anulados: 'ዝተሰረዙ',
  'Diagnóstico do servidor': 'ምርመራ ሰርቨር',
  'A carregar o stock…': 'ክምችት ይጽዓን ኣሎ…',
  'pré-preenchido com o registo de {d} · confirme': 'ብመዝገብ {d} ተመሊኡ · ኣረጋግጹ',
  'Localização aproximada pelo endereço IP (país e cidade, raio indicado), calculada no servidor com base de dados local. IP Geolocation by DB-IP.':
    'ግምታዊ ቦታ ብኣድራሻ IP (ሃገርን ከተማን፡ ምስ ዝተገልጸ ራዲየስ)፡ ኣብ ሰርቨር ብናይ ውሽጢ ዳታቤዝ ዝተሰልሐ። IP Geolocation by DB-IP.',
  Localização: 'ቦታ',
  'Rede interna': 'ውሽጣዊ መርበብ',
  'Endereço da rede da empresa, VPN ou do próprio servidor': 'ኣድራሻ መርበብ ትካል፡ VPN ወይ ናይ እቲ ሰርቨር',
  mapa: 'ካርታ',
  'Localização aproximada pelo IP, não é uma morada.': 'ግምታዊ ቦታ ብIP እዩ፡ ኣድራሻ መንበሪ ኣይኮነን።',
  'Calculada depois do registo.': 'ድሕሪ ምምዝጋብ ዝተሰልሐ።',
  Equipamentos: 'መሳርሒታት',
  Equipamento: 'መሳርሒ',
  '{a} smartphones · {b} impressoras': '{a} ስማርትፎናት · {b} ማሕተሚታት',
  Atribuídos: 'ዝተመደቡ',
  Atribuído: 'ዝተመደበ',
