    'ምስቲ ተመሳሳሊ መዓልቲ ሰሙን ኣብ ዝሓለፉ 6 ሰሙናት ብምንጽጻር (ማእከላይ)። ነፍሲ ወከፍ መጠንቀቕታ እንታይ ከም ዘጋጠመ፡ እንታይ ይጽበ ከም ዝነበረን ስለምንታይን ይገልጽ፤ ውሳነ ኩሉ ግዜ ናይቲ ዘንብቦ እዩ።',
  'Todos os dias às 07:00 segue por correio electrónico o resumo de ontem para os perfis com «Resumo diário» na matriz de acessos.':
    'ኩሉ መዓልቲ ኣብ 07:00 ጽማቕ ትማሊ ብኢመይል ናብቶም ኣብ ሰንጠረዥ መእተዊ «ዕለታዊ ጽማቕ» ዘለዎም ፕሮፋይላት ይለኣኽ።',
  'Ver o resumo de ontem': 'ጽማቕ ትማሊ ርአ',
  'Enviar-me um teste': 'ፈተና ስደደለይ',
