  'último envio: {d}': 'ናይ መወዳእታ ምልኣኽ፦ {d}',
  'correio electrónico por configurar no servidor': 'ኢመይል ኣብ ሰርቨር ገና ኣይተዳለወን',
  'Ainda não há histórico suficiente para prever (são precisas pelo menos 3 semanas de vendas).': 'ንምትንባይ እኹል ታሪኽ ገና የለን (እንተወሓደ 3 ሰሙናት መሸጣ የድሊ)።',
  'Previsão dos próximos 7 dias': 'ትንበያ ናይ ዝመጽኡ 7 መዓልታት',
