  Tendência: 'ኣንፈት',
  'últimas 4 semanas face às 4 anteriores (amortecida, no máximo ±20%)': 'ዝሓለፉ 4 ሰሙናት ምስ ቅድሚኡ 4 ብምንጽጻር (ዝተለዝበ፡ ብዝለዓለ ±20%)',
  'Precisão medida': 'ዝተዓቀነ ልክዕነት',
  'nos últimos {n} dias, com os dados de antes de cada dia': 'ኣብ ዝሓለፉ {n} መዓልታት፡ ብሓበሬታ ቅድሚ ነፍሲ ወከፍ መዓልቲ',
  real: 'ናይ ብሓቂ',
  previsto: 'ዝተተንበየ',
  'intervalo de 80%': '80% ክሊ',
  'Vendas reais (últimos 14 dias)': 'ናይ ብሓቂ መሸጣታት (ዝሓለፉ 14 መዓልታት)',
  'todas as rotas a que tem acesso': 'ኩሎም መስመራት ዘለኻ መእተዊ',
