  'Painel da sala comercial': 'ሰሌዳ ክፍሊ ንግዲ',
  'Ecrã de TV com as vendas do dia, actualizado a cada 2 minutos.': 'ስክሪን ቴሌቪዥን ምስ መሸጣታት ሎሚ፡ ኣብ ነፍሲ ወከፍ 2 ደቓይቕ ዝሕደስ።',
