  Criar: 'ፍጠር',
  'Abra este endereço no navegador do ecrã (em ecrã inteiro). Por segurança, só é mostrado agora: copie-o já.':
    'ነዚ ኣድራሻ ኣብ መርበብ ስክሪን ክፈቶ (ምሉእ ስክሪን)። ንውሕስነት ሕጂ ጥራይ እዩ ዝርአ፦ ሕጂ ቅድሖ።',
  'fora do habitual: {f}× o que costuma levar': 'ካብ ልሙድ ወጻኢ፦ {f}× ካብቲ ዝለመዶ',
