  'Aceitou o texto do consentimento em {d}.': 'ጽሑፍ ፍቓድ ኣብ {d} ተቐቢሉ።',
  'Ver a localização no mapa': 'ቦታ ኣብ ካርታ ርአ',
  'Aprovar o pedido': 'ሕቶ ኣጽድቕ',
