  'Pedidos dos clientes': 'ሕቶታት ዓማዊል',
  'Feitos pelos clientes no código QR do cartaz. Nada muda sem validação: as encomendas aprovadas avisam o promotor da rota; os dados aprovados ficam na lista para lançar no Pinguim BO.':
    'ብዓማዊል ብQR ናይ ፖስተር ዝቐረቡ። ብዘይ ምርግጋጽ ዝቕየር የለን፦ ዝጸደቓ ትእዛዛት ንወኪል መሸጣ መስመር ይሕብራ፤ ዝጸደቐ ሓበሬታ ናብ Pinguim BO ንምእታው ኣብ ዝርዝር ይጸንሕ።',
  'Escolha pelo menos um cliente.': 'እንተወሓደ ሓደ ዓሚል ምረጽ።',
