  'Apps no telemóvel': 'ኣፕታት ኣብ ሞባይል',
  '{a} equipamentos activos · {r} registados · {p} pessoas.': '{a} ንጡፋት መሳርሒታት · {r} ዝተመዝገቡ · {p} ሰባት።',
  'A app instala-se só pelo código QR pessoal do portal; cada pessoa tem um equipamento activo e o anterior é desactivado ao activar outro.':
    'እቲ ኣፕ ብውልቃዊ QR ኮድ ናይቲ ፖርታል ጥራይ ይጽዓን፤ ነፍሲ ወከፍ ሰብ ሓደ ንጡፍ መሳርሒ ኣለዎ፣ ካልእ ምስ ዝነጥፍ እቲ ዝቐደመ ይቋረጽ።',
  App: 'ኣፕ',
  Biometria: 'ባዮሜትሪ',
  'Activada em': 'ዝነጥፈሉ',
  'Última utilização': 'ናይ መወዳእታ ኣጠቓቕማ',
  Desactivar: 'ኣቋርጽ',
  'Desactivar a app': 'ኣፕ ኣቋርጽ',
  'A app de {n} deixa de funcionar neste equipamento. Para voltar a usá-la, a pessoa lê um código QR novo no portal.':
    'ናይ {n} ኣፕ ኣብዚ መሳርሒ ምስራሕ የቋርጽ። ከም ብሓድሽ ንምጥቃም፣ እቲ ሰብ ኣብ ፖርታል ሓድሽ QR ኮድ የንብብ።',
  'Código QR da app gerado': 'QR ኮድ ኣፕ ተዳልዩ',
  'App activada num equipamento': 'ኣፕ ኣብ መሳርሒ ነጢፉ',
  'App substituída por outro equipamento': 'ኣፕ ብካልእ መሳርሒ ተተኪኡ',
  'App desactivada': 'ኣፕ ተቛሪጹ',
  'Biometria da app activada': 'ባዮሜትሪ ኣፕ ነጢፉ',
