  'Passou nos testes de fumo: teste-a antes de a aprovar': 'ናይ መጀመርታ ፈተናታት ሓሊፉ፡ ቅድሚ ምጽዳቑ ፈትኖ',
  'Falhou nos testes de fumo': 'ኣብ ናይ መጀመርታ ፈተናታት ኣይሓለፈን',
  'Pinguim BO (SQL Server, só leitura)': 'Pinguim BO (SQL Server፡ ንምንባብ ጥራይ)',
