  'Valores da Naval, definidos pela Direcção. A zero, a parcela fica por definir e não entra no total.':
    'ብኣመራርሓ ዝውሰኑ ዋጋታት ናቫል። ብዜሮ እንተኾይኑ፡ እቲ ክፋል ኣይተወሰነን ኣብ ድምር ድማ ኣይኣቱን።',
