  'Últimos {n} meses': 'ናይ መወዳእታ {n} ኣዋርሕ',
  'Por definir pela Direcção': 'ብኣመራርሓ ክውሰን ዘለዎ',
  'Sem estes valores, a parcela correspondente não entra no total.': 'ብዘይ እዞም ዋጋታት፡ እቲ ዝምልከቶ ክፋል ኣብ ድምር ኣይኣቱን።',
