  'Contagens reais do portal e do Pinguim BO; valores em Kz.': 'ሓቀኛ ቁጽርታት ካብ ፖርታልን Pinguim BOን፤ ዋጋታት ብ Kz።',
  'Rotas conciliadas': 'ዝተሰማምዑ መስመራት',
  'Fechos automáticos': 'ብባዕሉ ዝተዓጽዉ',
  'Ficheiros SAP': 'ፋይላት SAP',
  Relatórios: 'ጸብጻባት',
  Horas: 'ሰዓታት',
  Tempo: 'ግዜ',
  Licenças: 'ፍቓዳት ሶፍትዌር',
  Construção: 'ምህናጽ',
  'Anulados corrigidos': 'ዝተሰረዙ ዝተኣረሙ',
