  'As notificações estão bloqueadas nas definições do telefone para esta app.': 'ምልክታታት ኣብ ቅጥዒ ስልኪ ንዚ መተግበሪ ተዓጽዮም ኣለዉ።',
  'As notificações não foram autorizadas.': 'ምልክታታት ኣይተፈቕዱን።',
