  'Este telefone ainda não tem as notificações ligadas.': 'እዚ ስልኪ ገና ምልክታታት ኣይወለዐን።',
  'O serviço de notificações do telefone não aceitou a mensagem. Volte a ligar as notificações.': 'ኣገልግሎት ምልክታታት ስልኪ ነቲ መልእኽቲ ኣይተቐበሎን። ምልክታታት ደጊምኩም ኣወልዑ።',
  'Serviço de notificações não reconhecido.': 'ዘይፍለጥ ኣገልግሎት ምልክታታት።',
