  'Sortido por promotor': 'ዓይነት ኣቕሑ ብወኪል መሸጣ',
  'Artigos A: os que somam 80% do valor do promotor (análise ABC). Clientes: os que compraram ao promotor no período (distribuição numérica).':
    'ኣቕሑ A፦ እቶም 80% ዋጋ ናይቲ ወኪል መሸጣ ዝገብሩ (ትንተና ABC)። ዓማዊል፦ እቶም ኣብቲ እዋን ካብቲ ወኪል መሸጣ ዝዓደጉ (ቍጽራዊ ምዝርጋሕ)።',
