    'መስመራት መሸጣ Pinguim BO ኣብቲ እዋን፣ ናይ ልቓሕ መግለጺታት ተቐኒሱ። ዋጋ ንሓደ ብዘይ ግ.ወ.ዋ፦ ዝተመዘነ ማእከላይ (ዋጋ ብዘይ ግ.ወ.ዋ ÷ ብዝሒ)። ምስ ማእከላይ፦ ፍልልይ ምስ ማእከላይ ዋጋ ናይቲ ኣቕሓ ኣብ ትካል። ህላወ፦ ነቲ ኣቕሓ ዘጠቓልሉ ሰነዳት ናይቲ ወኪል መሸጣ።',
