    'ቍጽርታት ኣረጋግጹ፦ ቅኑዕ እንተኾይኑ ኣጽድቑ፤ እንተዘይኮይኑ ደጊምኩም ቍጸሩ። ድሕሪ ምርግጋጽ ናብ ኣወሃሃዲ ይሓልፍ።',
