  'Contagem validada; segue para o coordenador. Foi criada a requisição de reposição com o que foi vendido.': 'ቆጸራ ተረጋጊጹ፤ ናብ ኣወሃሃዲ ይሓልፍ። ሕቶ ምትካእ ብዝተሸጠ ተፈጢሩ።',
  'Vendas do Pinguim BO completas (todos os telemóveis sincronizados depois do fecho)': 'መሸጣታት Pinguim BO ምሉእ (ኩሎም ተሌፎናት ድሕሪ ሰዓት መዕጸዊ ተሰማሚዖም)',
  'Conciliação de todas as carrinhas fechada': 'ምትዕራቕ ኩለን መካይን ተዓጽዩ',
  'Vendas do dia carregadas no SAP': 'መሸጣታት ናይታ መዓልቲ ናብ SAP ተጻዒኖም',
