  'Relatório de Vendas do Marketing (resumo, cobranças por promotor, caixa, registo de vendas e stock das carrinhas), gerado só com todas as fontes do dia completas, e folha de caixa da tesouraria.':
    "ጸብጻብ መሸጣ ማርኬቲንግ (ጽማቕ፣ ኣከፋፍላታት ብወኪል መሸጣ፣ ካዝና፣ መዝገብ መሸጣን ንብረት መካይንን)፣ ኩሎም ምንጭታት ናይታ መዓልቲ ምሉኣት ክኾኑ ከለዉ ጥራይ ዝዳሎ፣ ከምኡ'ውን ወረቐት ካዝና ግምጃ ቤት።",
