  'Retirar {k} do ficheiro de configuração: a ligação tem de ir cifrada.': '{k} ካብ ፋይል ኣቀማምጣ ኣውጽእ፤ እቲ ምትእስሳር ምስጢራዊ ክኸውን ኣለዎ።',
  'Instalar no SQL Server um certificado emitido para o nome do servidor (autoridade de certificação da empresa ou pública) e reiniciar o serviço; o portal passa a validá-lo sozinho.':
    'ኣብ SQL Server ንስም ናይቲ ሰርቨር ዝተዋህበ ሰርቲፊኬት (ናይ ትካል ወይ ህዝባዊ ኣውጻኢ) ኣቐምጥን ነቲ ኣገልግሎት ዳግማይ ጀምሮን፤ እቲ ፖርታል ባዕሉ የረጋግጾ።',
  'Instalar o {c} (o controlador antigo não a suporta).': '{c} ኣቐምጥ (እቲ ናይ ቀደም መዘውር ኣይድግፎን)።',
  'Ligações às bases de dados': 'ምትእስሳራት ምስ ዳታቤዝ',
  '{n} controlos fora da norma: o portal liga-se da forma mais segura que o servidor permite e volta a verificar sozinho.':
    '{n} ቁጽጽራት ካብ ስርዓት ወጻኢ፤ እቲ ፖርታል ብቲ ሰርቨር ዘፍቅዶ ዝበለጸ ውሑስ መንገዲ ይራኸብን ባዕሉ ደጊሙ ይፍትሽን።',
  'Todas as ligações cumprem a configuração de referência (ISO/IEC 27001 A.8.24, A.5.15).': 'ኩሎም ምትእስሳራት ነቲ መወከሲ ኣቀማምጣ የማልኡ (ISO/IEC 27001 A.8.24, A.5.15)።',
