  'Fecho de caixa (movimentos)': 'ምዕጻው ካሳ (ምንቅስቓሳት)',
  'Conciliação das carrinhas (artigos)': 'ምስምማዕ መካይን (ኣቕሑ)',
  'Documentos de venda e notas de crédito do período, como nas páginas de vendas (substituições de facturas à parte).':
    'ሰነዳት መሸጣን ናይ ክረዲት ማስታወሻታትን ናይቲ እዋን፣ ከምቶም ገጻት መሸጣ (ምትካእ ፋክቱራታት በይኑ)።',
  'Linhas de artigo dos documentos de venda do período.': 'መስመራት ኣቕሓ ናይ ሰነዳት መሸጣ ናይቲ እዋን።',
  'Valores cobrados por documento e meio de cobrança.': 'ዝተኣከቡ መጠናት ብሰነድን ብመገዲ ክፍሊትን።',
  'Clientes da carteira por rota e dia de visita (situação actual).': 'ዓማዊል ፖርትፎልዮ ብመስመርን መዓልቲ ምብጻሕን (ናይ ሕጂ ኩነታት)።',
  'Novos clientes registados pelos promotores (cadastros RTM).': 'ብወከልቲ ዝተመዝገቡ ሓደስቲ ዓማዊል (ምዝገባታት RTM)።',
  'Carga de cada carrinha por dia (plano de cargas).': 'ጽዕነት ነፍሲ ወከፍ መኪና ብመዓልቲ (መደብ ጽዕነት)።',
  'Posição de stock no último dia do período, por carrinha e armazém.': 'ኩነታት ክምችት ኣብ መወዳእታ መዓልቲ ናይቲ እዋን፣ ብመኪናን መኽዘንን።',
  'Requisições de reposição das carrinhas do período, por estado.': 'ሕቶታት ምምላእ መካይን ናይቲ እዋን፣ ብኩነታት።',
  'Resumo diário do fecho de caixa: saldo inicial, entregas, Multicaixa, depósitos, contagem e diferença.':
    'መዓልታዊ ጽማቝ ምዕጻው ካሳ፦ መበገሲ ሚዛን፣ ዝተረከበ ገንዘብ፣ Multicaixa፣ ተቐማጢ፣ ቆጸራን ፍልልይን።',
  'Entregas por promotor, talões do TPA e depósitos no banco, linha a linha.': "ዝተረከበ ገንዘብ ብወኪል፣ ቅብሊታት TPA ከምኡ'ውን ተቐማጢ ባንኪ፣ መስመር ብመስመር።",
  'Carregado, vendido e contado por rota e dia, com as diferenças e o seu valor (rotas contadas).':
    'ዝተጻዕነ፣ ዝተሸጠን ዝተቖጽረን ብመስመርን መዓልትን፣ ምስ ፍልልያትን ዋጋኦምን (ዝተቖጽሩ መስመራት)።',
  'Cada artigo da conciliação: inicial, carregado, vendido, devolvido, esperado, contado e diferença.':
    'ነፍሲ ወከፍ ኣቕሓ ምስምማዕ፦ መበገሲ፣ ዝተጻዕነ፣ ዝተሸጠ፣ ዝተመልሰ፣ ዝጽበ፣ ዝተቖጽረን ፍልልይን።',
  'Pedidos feitos pelos clientes pelo código QR (pendentes e decididos nos últimos 30 dias).': 'ብዓማዊል ብኮድ QR ዝቐረቡ ሕቶታት (ዝጽበዩን ኣብ ዝሓለፉ 30 መዓልታት ዝተወሰኑን)።',
  'Alertas de anomalias do último dia útil, com o tratamento (assumido, resolvido, silenciado).':
    'መጠንቀቕታታት ዘይንቡር ናይ መወዳእታ መዓልቲ ስራሕ፣ ምስ ኣተኣላልያኦም (ዝተሓዘ፣ ዝተፈትሐ፣ ዝሰቀጠ)።',
  'Smartphones e impressoras do terreno, por tipo, estado e colaborador.': 'ናይ መዳይ ሞባይላትን መሕተምታትን፣ ብዓይነት፣ ኩነታትን ሰራሕተኛን።',
  'Pedidos de suporte e incidentes (os seus; quem gere vê todos).': 'ሕቶታት ደገፍን ፍጻመታትን (ናትካ፤ ዘመሓድር ኩሉ ይርኢ)።',
  'Pinguim BO e cadastros RTM': "Pinguim BO ከምኡ'ውን ምዝገባታት RTM",
  'Cadastros RTM': 'ምዝገባታት RTM',
