  'Criar relatório (V: criar e guardar os seus; G: também partilhar com todos)': "ጸብጻብ ፍጠር (V: ናትካ ፍጠርን ዓቅብን፤ G: ምስ ኩሉ'ውን ተኻፈል)",
  'Relatórios · certificar (selo «certificado»; outra pessoa que não o autor)': 'ጸብጻባት · ኣረጋግጽ (ማሕተም «ዝተረጋገጸ»፤ ካልእ ሰብ ደኣምበር እቲ ደራሲ ኣይኮነን)',
