  certificado: 'ዝተረጋገጸ',
  'Receber por correio': 'ብኢመይል ተቐበል',
  'Não receber': 'ኣይትቐበል',
  'Todos os dias (07:30)': 'ኩሉ መዓልቲ (07:30)',
  'Às segundas-feiras (07:30)': 'ኣብ ሰኑያት (07:30)',
  'No dia 1 de cada mês (07:30)': 'ኣብ 1 ናይ ነፍሲ ወከፍ ወርሒ (07:30)',
  'Deixou de receber este relatório por correio.': 'ነዚ ጸብጻብ ብኢመይል ምቕባል ኣቋሪጽካ።',
  'Vai receber um aviso por correio com a ligação para este relatório.': 'ምስ መላግቦ ናብዚ ጸብጻብ ናይ ኢመይል መዘኻኸሪ ክትቕበል ኢኻ።',
  'O correio leva só o aviso e a ligação: por segurança, os números vêem-se no portal, com as suas permissões.':
    'እቲ ኢመይል መዘኻኸርን መላግቦን ጥራይ ይሕዝ፤ ንድሕነት፣ እቶም ቁጽርታት ኣብ ፖርታል ብፍቓድካ ይርአዩ።',
  '1 pessoa recebe este relatório por correio.': '1 ሰብ ነዚ ጸብጻብ ብኢመይል ይቕበል።',
  '{n} pessoas recebem este relatório por correio.': '{n} ሰባት ነዚ ጸብጻብ ብኢመይል ይቕበሉ።',
  'Previsão de vendas, assistente de IA, painel da sala comercial, gráficos de gestão, resumo diário, fecho do dia, app de gestão, valor do portal para a Naval e explorador de relatórios (criar, guardar, partilhar e certificar relatórios).':
    'ትንበያ መሸጣ፡ ሓጋዚ ሰብ ሰራሕ ኣእምሮ፡ ሰሌዳ ክፍሊ ንግዲ፡ ሰንጠረዛት ምሕደራ፡ ዕለታዊ ጽማቝ፡ መዕጸዊ መዓልቲ፡ መተግበሪ ምሕደራ፡ ዋጋ ፖርታል ንናቫልን መዳህሰሲ ጸብጻባትን (ጸብጻባት ፍጠር፣ ዓቅብ፣ ተኻፈልን ኣረጋግጽን)።',
  'Contagem final de todo o dinheiro que está na caixa, nota a nota: saldo do dia anterior + entregas − depósitos. As contagens das entregas conferem cada promotor; esta confere a caixa inteira.':
    'ናይ መወዳእታ ቆጸራ ኩሉ ኣብ ሳጹን ዘሎ ገንዘብ፡ ወረቐት ብወረቐት፦ ሕሳብ ናይ ዝሓለፈት መዓልቲ + ዝተረከበ − ዝተቐመጠ። ቆጸራታት ናይ ምርካብ ነፍሲ ወከፍ ወኪል ይፍትሹ፤ እዚ ድማ ንብምሉኡ ሳጹን ይፍትሽ።',
  'Contagem às cegas: o saldo esperado só é comparado depois de validar, para a contagem ser independente.':
    'ዕዉር ቆጸራ፦ እቲ ዝድለ ሕሳብ ድሕሪ ምርግጋጽ ጥራይ ይነጻጸር፡ ቆጸራ ናጻ ምእንቲ ክኸውን።',
  'A contagem não bate com o saldo esperado (diferença de {v}). Conte de novo as notas e volte a validar; se a diferença se mantiver, explique-a.':
    'እቲ ቆጸራ ምስቲ ዝድለ ሕሳብ ኣይሰማማዕን (ፍልልይ {v})። ነቶም ወረቓቕቲ ደጊምካ ቁጸሮም እሞ ደጊምካ ኣረጋግጽ፤ እቲ ፍልልይ እንተቐጸለ ግለጾ።',
  'A diferença mantém-se ({v}). Explique-a para validar a caixa; fica registada para a aprovação.': 'እቲ ፍልልይ ቀጺሉ ኣሎ ({v})። ነቲ ሳጹን ንምርግጋጽ ግለጾ፤ ንምጽዳቕ ይምዝገብ።',
  'A sessão termina em {s} s.': 'እቲ ክፍለ-ግዜ ኣብ {s} ካልኢት ይዛዘም።',
  'Sessão sem actividade': 'ክፍለ-ግዜ ብዘይ ምንቅስቓስ',
  'Por segurança, a sessão termina após {m} minutos sem actividade.': 'ንድሕነት፡ እቲ ክፍለ-ግዜ ድሕሪ {m} ደቓይቕ ዘይምንቅስቓስ ይዛዘም።',
  'Tem alterações por gravar: continue ligado e grave-as.': 'ዘይተዓቀበ ለውጥታት ኣለኩም፦ ተራኺብኩም ጽንሑ እሞ ዕቀብዎም።',
  'Continuar ligado': 'ተራኺብካ ጽናሕ',
  'Modo apresentação': 'ኣገባብ ምቕራብ',
  'Para apresentar com o computador ligado a um projector ou LCD. Durante o período escolhido, a sessão só termina após 60 minutos sem actividade e o portal não volta sozinho ao painel. Acaba sozinho à hora marcada e fica registado.':
    'ኮምፒተር ምስ ፕሮጀክተር ወይ ስክሪን ተራኺቡ ንምቕራብ። ኣብቲ ዝተመርጸ ግዜ፡ እቲ ክፍለ-ግዜ ድሕሪ 60 ደቓይቕ ዘይምንቅስቓስ ጥራይ ይዛዘም፡ እቲ ፖርታል ድማ ባዕሉ ናብ ዳሽቦርድ ኣይምለስን። ኣብቲ ዝተወሰነ ሰዓት ባዕሉ ይውዳእ፡ ይምዝገብ ድማ።',
  'Duração da apresentação': 'ንውሓት ምቕራብ',
