  'Um cliente por linha: rota, dias de visita, estado do cadastro, GPS e se comprou no período. Toque no nome para abrir a ficha do cliente.':
    'ሓደ ዓሚል ብረድፊ፦ መስመር፡ መዓልታት ምብጻሕ፡ ኩነታት ምዝገባ፡ ጂፒኤስን ኣብቲ እዋን ዓዲጉ እንተኾይኑን። ፋይል ዓሚል ንምኽፋት ኣብ ስም ጠውቑ።',
